const item = $input.item.json;
const SUPABASE_URL = $env.SUPABASE_URL || 'https://uzghfpxboktnbcbbthns.supabase.co';
const SERVICE_KEY  = $env.SUPABASE_SERVICE_KEY;
const ANON_KEY     = $env.SUPABASE_ANON_KEY;
const N8N_BASE_URL = $env.N8N_BASE_URL || 'https://n8n.srv1649259.hstgr.cloud';

const VALID_STYLES = ['scandinavian','japandi','midcentury','traditional','industrial','boho'];
const VALID_ROOMS  = ['bedroom','kids room','dining room','kitchen','mandir','living room'];

function errResult(error, phase, detail) {
  return [{ json: { file_index: item.file_index ?? 0, status: 'error', error, phase, detail: detail || null } }];
}

// 1. Validate inputs
const { file_b64, file_mime, filename, style_tag, room_type, user_id, bearer_token } = item;
const file_index = item.file_index ?? 0;

if (!file_b64) return errResult('missing_file_b64', 'validate');
if (!VALID_STYLES.includes(style_tag)) return errResult(`invalid_style_tag: ${style_tag}`, 'validate');
if (!VALID_ROOMS.includes(room_type))  return errResult(`invalid_room_type: ${room_type}`, 'validate');
if (!file_mime || !file_mime.startsWith('image/')) return errResult('invalid_mime_type', 'validate');
if (!user_id || !bearer_token) return errResult('missing_user_credentials', 'validate');

const b64Bytes = Math.floor(file_b64.length * 3 / 4);
if (b64Bytes > 10 * 1024 * 1024) return errResult('file_too_large_max_10mb', 'validate');

// 2. Prepare storage path
const ext = file_mime === 'image/png' ? 'png' : file_mime === 'image/webp' ? 'webp' : 'jpg';
const uuid = require('crypto').randomUUID();
const storage_path = `studio/${user_id}/${style_tag}/${room_type}/${uuid}.${ext}`;
const source_url   = `${SUPABASE_URL}/storage/v1/object/reference-images/${storage_path}`;

// 3. Upload binary to Supabase Storage (service key — server-side)
const binary = Buffer.from(file_b64, 'base64');
let uploadResp;
try {
  uploadResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/storage/v1/object/reference-images/${storage_path}`,
    headers: { 'Authorization': `Bearer ${SERVICE_KEY}`, 'Content-Type': file_mime, 'x-upsert': 'false' },
    body: binary,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch(e) {
  return errResult('storage_upload_exception', 'storage', e.message);
}
if (uploadResp.statusCode !== 200) {
  return errResult('storage_upload_failed', 'storage', uploadResp.body);
}

// Helper: delete storage object (compensating action on later failures)
async function deleteStorage() {
  try {
    await this.helpers.httpRequest({
      method: 'DELETE',
      url: `${SUPABASE_URL}/storage/v1/object/reference-images/${storage_path}`,
      headers: { 'Authorization': `Bearer ${SERVICE_KEY}`, 'apikey': SERVICE_KEY },
      ignoreHttpStatusErrors: true,
    });
  } catch(_) {}
}

// 4. Get 5-min signed URL for the captioner to fetch the image
let signResp;
try {
  signResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/storage/v1/object/sign/reference-images/${storage_path}`,
    headers: { 'Authorization': `Bearer ${SERVICE_KEY}`, 'apikey': SERVICE_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ expiresIn: 300 }),
    ignoreHttpStatusErrors: true,
  });
} catch(e) {
  await deleteStorage.call(this);
  return errResult('signed_url_exception', 'storage', e.message);
}
const signedPath = signResp.signedURL || signResp.signedUrl || signResp.signed_url;
if (!signedPath) {
  await deleteStorage.call(this);
  return errResult('signed_url_missing', 'storage', signResp);
}
const signed_url = signedPath.startsWith('http') ? signedPath : `${SUPABASE_URL}${signedPath}`;

// 5. Call caption_generate webhook
let captionResp;
try {
  captionResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${N8N_BASE_URL}/webhook/caption/generate`,
    headers: { 'Authorization': `Bearer ${bearer_token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ image_url: signed_url, style_tag, room_type }),
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch(e) {
  await deleteStorage.call(this);
  return errResult('caption_exception', 'caption', e.message);
}
if (captionResp.statusCode !== 200) {
  await deleteStorage.call(this);
  return errResult('caption_failed', 'caption', captionResp.body);
}
const captionBody = captionResp.body;
if (captionBody.error || !captionBody.caption) {
  await deleteStorage.call(this);
  return errResult('caption_parse_error', 'caption', captionBody);
}
const { caption, spatial_signature } = captionBody;

// 6. Insert reference_images row using user's bearer (RLS enforces owner_id)
let insertResp;
try {
  insertResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/reference_images`,
    headers: {
      'Authorization': `Bearer ${bearer_token}`,
      'apikey': ANON_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    },
    body: JSON.stringify({
      owner_id: user_id,
      source: 'studio',
      source_id: uuid,
      source_url,
      license: 'owned',
      storage_path,
      caption,
      spatial_signature,
      room_type,
      style_tags: [style_tag],
    }),
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch(e) {
  await deleteStorage.call(this);
  return errResult('insert_exception', 'database', e.message);
}
if (insertResp.statusCode !== 201) {
  await deleteStorage.call(this);
  return errResult('insert_failed', 'database', insertResp.body);
}

const inserted = Array.isArray(insertResp.body) ? insertResp.body[0] : insertResp.body;
return [{ json: {
  file_index,
  status: 'ok',
  id: inserted.id,
  storage_path,
  caption_preview: caption.slice(0, 200),
} }];
